drop policy if exists comanda_accounts_insert on public.comanda_accounts;
create policy comanda_accounts_insert on public.comanda_accounts for insert to authenticated with check(owner_id=(select auth.uid()));
drop policy if exists comanda_audit_insert on public.comanda_audit_logs;
create policy comanda_audit_insert on public.comanda_audit_logs for insert to authenticated with check(private.comanda_has_account_access(account_id) and user_id=(select auth.uid()));
drop policy if exists comanda_members_manage on public.comanda_members;
create policy comanda_members_insert on public.comanda_members for insert to authenticated with check(private.comanda_is_account_admin(account_id));
create policy comanda_members_update on public.comanda_members for update to authenticated using(private.comanda_is_account_admin(account_id)) with check(private.comanda_is_account_admin(account_id));
create policy comanda_members_delete on public.comanda_members for delete to authenticated using(private.comanda_is_account_admin(account_id));
create index if not exists comanda_accounts_owner_idx on public.comanda_accounts(owner_id);
create index if not exists comanda_members_user_idx on public.comanda_members(user_id);
create index if not exists comanda_branches_account_idx on public.comanda_branches(account_id);
create index if not exists comanda_staff_account_branch_idx on public.comanda_staff(account_id,branch_id);
create index if not exists comanda_cash_registers_account_branch_idx on public.comanda_cash_registers(account_id,branch_id);
create index if not exists comanda_cash_sessions_account_register_status_idx on public.comanda_cash_sessions(account_id,register_id,status);
create index if not exists comanda_sectors_account_branch_idx on public.comanda_sectors(account_id,branch_id);
create index if not exists comanda_tables_account_sector_idx on public.comanda_tables(account_id,sector_id);
create index if not exists comanda_tables_branch_idx on public.comanda_tables(branch_id);
create index if not exists comanda_categories_account_branch_idx on public.comanda_categories(account_id,branch_id);
create index if not exists comanda_products_account_category_idx on public.comanda_products(account_id,category_id);
create index if not exists comanda_orders_account_branch_status_idx on public.comanda_orders(account_id,branch_id,status,opened_at desc);
create index if not exists comanda_orders_waiter_idx on public.comanda_orders(waiter_id);
create index if not exists comanda_order_items_account_order_idx on public.comanda_order_items(account_id,order_id,created_at);
create index if not exists comanda_order_items_product_idx on public.comanda_order_items(product_id);
create index if not exists comanda_order_items_kitchen_idx on public.comanda_order_items(account_id,kitchen_status,sent_at) where kitchen_status in('pending','preparing','ready');
create index if not exists comanda_payments_account_order_idx on public.comanda_payments(account_id,order_id,created_at);
create index if not exists comanda_payments_cash_session_idx on public.comanda_payments(cash_session_id);
create index if not exists comanda_audit_account_created_idx on public.comanda_audit_logs(account_id,created_at desc);
create index if not exists comanda_cash_movements_account_session_idx on public.comanda_cash_movements(account_id,cash_session_id,created_at desc);